from copy import deepcopy


def option(option_id: str, name: str, price: float = 0, default: bool = False):
    return {
        "id": option_id,
        "name": name,
        "priceDelta": price,
        "defaultSelected": default,
        "enabled": True,
        "available": True,
    }


